def import_bundle(self, bundle):
    if not isinstance(bundle, dict):
        raise ValueError("bundle must be an object")
    datasets = bundle.get("datasets")
    if not isinstance(datasets, list):
        raise ValueError("bundle must contain a datasets array")
    records = self.entries()
    new_entries = {}
    for dataset in datasets:
        entry = _normalize_descriptor(dataset, set(records) | set(new_entries))
        new_entries[entry["id"]] = entry

    remaining = {key: {dep for dep in entry["depends_on"] if dep in new_entries}
                 for key, entry in new_entries.items()}
    ready = [key for key, deps in remaining.items() if not deps]
    heapq.heapify(ready)
    ordered = []
    while ready:
        key = heapq.heappop(ready)
        ordered.append(key)
        for other, deps in remaining.items():
            if key in deps:
                deps.remove(key)
                if not deps:
                    heapq.heappush(ready, other)
    if len(ordered) != len(new_entries):
        raise ValueError("dependency cycle detected")

    added = [new_entries[key] for key in ordered]
    if added:
        for entry in added:
            records[entry["id"]] = entry
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.path.write_text(json.dumps(records, ensure_ascii=False, indent=2) + "\n",
                             encoding="utf-8")
    return {"datasets": added}

